diff --git a/mail/components/accountcreation/views/email.mjs b/mail/components/accountcreation/views/email.mjs
index acc797ba235..8e6ba771915 100644
--- a/mail/components/accountcreation/views/email.mjs
+++ b/mail/components/accountcreation/views/email.mjs
@@ -417,8 +417,13 @@ class AccountHubEmail extends HTMLElement {
    * Initialize the UI of one of the email setup subviews.
    *
    * @param {string} subview - Subview for which the UI is being initialized.
+   * @param {boolean} [isReset=false] - Initing to reset the view (like on close).
    */
-  async #initUI(subview) {
+  async #initUI(subview, isReset = false) {
+    if (!isReset) {
+      Glean.mail.accountHubLoaded.record({ view_name: subview });
+    }
+
     this.#hideSubviews();
     this.#clearNotifications();
     this.#currentState = subview;
@@ -1883,7 +1888,7 @@ class AccountHubEmail extends HTMLElement {
     }

     this.#stopLoading();
-    await this.#initUI("autoConfigSubview");
+    await this.#initUI("autoConfigSubview", true);
     this.#currentState = "autoConfigSubview";
     this.#currentConfig = null;
     this.#exchangeUsername = "";
diff --git a/mail/metrics.yaml b/mail/metrics.yaml
index db34e3c9961..8d381a9c253 100644
--- a/mail/metrics.yaml
+++ b/mail/metrics.yaml
@@ -642,3 +642,21 @@ mail:
       ui:
         description: Identifies the code handling the certificate exception.
         type: string
+
+  account_hub_loaded:
+    type: event
+    description: >
+      Tracks each time an account hub view was loaded.
+    bugs:
+      - https://bugzilla.mozilla.org/show_bug.cgi?id=1983678
+    data_reviews:
+      - https://bugzilla.mozilla.org/show_bug.cgi?id=1983678#cXXX
+    data_sensitivity:
+      - technical
+    notification_emails:
+      - telemetry-client-dev@thunderbird.net
+    expires: never
+    extra_keys:
+      view_name:
+        description: Name of the view or subview.
+        type: string
